        'content': 'Most regulatory signs in Nigeria are circular in shape. They are often color-coded as follows:\n\n- Prohibitive signs (signs that tell you what you must not do) usually have a red border. Many have a white background with a red circle and sometimes a diagonal red slash. For example, "No U-turn" or "No Horn" signs use a red circle with a symbol inside.\n\n- Mandatory signs (signs that tell you what you must do or a positive instruction) are often blue circles with a symbol, and no red border. These might indicate a required movement (like "turn left only" or "keep right").\n\n- A unique regulatory sign is the STOP sign, which is the only sign that is an octagon (eight-sided shape) and is red with white lettering. Another unique one is the YIELD (Give Way) sign, which is an inverted triangle (point down) with a red border. All other common regulatory signs are circular.',
