      },
      {
        'type': 'paragraph',
        'content': 'Center Lines: Most roads have a center line separating opposite directions of traffic. If the center line is a broken (dashed) white line, it means you may overtake or cross it if it\'s safe to do so. If the center line is a continuous solid line, it means no crossing – you must stay on your side of the road. Often, you will see one solid line with one broken line alongside it: if the solid line is on your side, you are not allowed to overtake or cross (but vehicles on the opposite side may, if their side is broken). If the broken line is on your side, you may overtake if safe, but traffic on the other side (with the solid line on their side) cannot. Always respect these lines; they are there based on road visibility. Crossing a solid line is dangerous and illegal.',
      },
      {
        'type': 'paragraph',
        'content': 'Lane Lines: On multi-lane roads, white broken (dashed) lines separate lanes moving in the same direction. You may change lanes over a broken white line with caution. Sometimes lanes may have solid white lines between them – a solid white lane line means lane changing is discouraged or not allowed (perhaps because you\'re approaching a hazard or an intersection). For example, near an intersection, the lane lines might turn solid to tell you to stay in your lane through the junction.',
      },
      {
        'type': 'paragraph',
        'content': 'Edge Lines: A solid white line along the outer edge of the road marks the road\'s shoulder. don\'t drive to the right of this line (off the road) except in an emergency or when pulling over. At night or in poor visibility, the edge line helps you stay on the road. Some roads use yellow edge lines on the left side if it\'s a divided highway (to mark the median side).',
      },
      {
        'type': 'image',
        'content': 'assets/images/Zebra_crossing.png',
      },
      {
        'type': 'paragraph',
        'content': 'Crosswalks (Pedestrian crossings): These are marked by broad white stripes on the road (zebra crossing), usually accompanied by warning signs and sometimes flashing yellow beacons. As mentioned, when approaching a crosswalk, slow down and be prepared to stop for people crossing. Do not park on or within the zigzag lines leading to a zebra crossing – those zig zag markings (white zigzag lines on each side of the crossing) indicate no parking/no overtaking zone. They ensure the driver\'s view of pedestrians is not blocked. Overtaking is prohibited at these approaches as well.',
      },
      {
        'type': 'image',
        'content': 'assets/images/Stop_lines_at_intersections.png',
      },
      {
        'type': 'paragraph',
        'content': 'Stop Lines and Give Way Lines: At intersections with STOP signs, you will see a thick stop line painted on the road, often accompanied by the word “STOP”. You must stop with your front tires before this line. At YIELD (Give Way) signs, you typically see a line of short broken white triangles painted across the lane (often called shark\'s teeth) indicating a yield line – you should stop before these if yielding to cross traffic.',
      },
      {
        'type': 'paragraph',
        'content': 'Arrows on Road: White arrows painted on your lane indicate permitted directions or upcoming requirements. For example, an arrow pointing straight only, or left only, or a combination like straight or left. Position your car according to these arrows – if you are in a lane marked for left turn only, you must turn left. If you realize you are in the wrong lane (say you intended to go straight but you\'re in a left-turn-only lane), follow the lane\'s instruction (turn left) rather than swerving last minute; then find a safe way to redirect later. It\'s safer and expected by other drivers.',
      },
      {
        'type': 'image',
        'content': 'assets/images/Yellow_box_junctions.png',
      },
      {
        'type': 'paragraph',
        'content': 'Yellow Box Junctions: In some busy intersections, you might see a yellow criss cross box painted on the road. The rule for a box junction is that you must not enter the box unless your exit is clear. In other words, do not stop and block that box area. These are often placed where blocking the intersection would cause traffic gridlock. If turning right at a box junction and you are prevented from exiting only by oncoming traffic or other vehicles waiting to turn right, you may wait in the box – but otherwise, do not enter it without a clear path out.',
      },
      {
        'type': 'paragraph',
        'content': 'Parking and Curb Markings: Yellow lines painted on the curb or edge can indicate parking restrictions. For instance, a single yellow line along the curb might indicate no parking during certain times (check signposts for times), while a double yellow line means no parking at any time. (These practices are common in many countries; local regulations in Nigeria may vary, but generally, do not park where the curb is marked yellow or where signs say “No Parking”). Red lines, if any, would indicate no stopping at any time (less common).',
      },
      {
        'type': 'image',
        'content': 'assets/images/Speed_bump_markings.png',
      },
      {
        'type': 'paragraph',
        'content': 'Speed Hump Markings: Speed bumps or humps may be painted with chevrons or stripes to make them visible. Slow down when you see these.',
      },
      {
        'type': 'image',
        'content': 'assets/images/Cycle_and_bus_lanes.png',
      },
      {
        'type': 'paragraph',
        'content': 'Colored Lanes: Sometimes, you may encounter painted cycle lanes (often green) or bus lanes (marked by words or colored pavement). Respect these – do not drive or park in a marked bicycle lane, and only drive in a bus lane if permitted by signs (usually bus lanes are operational at certain times and open to normal traffic outside those times; check signboards). Driving in a lane dedicated for buses or BRT (Bus Rapid Transit) without permission can result in fines.',
      },
      {
        'type': 'paragraph',
        'content': 'In summary, informative signs help you navigate and find services, while road markings guide your positioning and actions on the road itself. Both are as important as standalone signs. A good driver constantly observes these markings: staying within lanes, respecting stop lines, and using the correct lane for turns.',
      },
    ],
  },
  '7.1': {
    'title': 'Lesson 7',
    'contentBlocks': [
      {
        'type': 'heading',
        'content': 'Lesson 7: Traffic Lights and Hand Signals - Traffic Light Meanings',
      },
      {
        'type': 'paragraph',
        'content': 'Traffic lights (traffic signals) are a fundamental method of controlling right-of-way at intersections. In Nigeria, as in most countries, the standard lights are Red, Yellow (Amber), and Green. It\'s crucial to understand what each light means and how to respond. Additionally, there are occasions where hand signals by drivers or signals by traffic officers come into play – these are also covered in this lesson.',
      },
      {
        'type': 'heading',
        'content': 'Traffic Light Colors and Meanings:',
      },
      {
        'type': 'image',
        'content': 'assets/images/Multiple_traffic_signals.png',
      },
      {
        'type': 'heading',
        'content': 'Red Light',
      },
      {
        'type': 'paragraph',
        'content': 'STOP. A red light means you must come to a complete stop before the stop line or crosswalk. You must wait behind the line until the light turns green. It is illegal and dangerous to run a red light. Always stop when the light is red, even if you think no other vehicles are coming – crossing on red could cause a serious side-impact collision.',
      },
      {
        'type': 'heading',
        'content': 'Green Light',
      },
      {
        'type': 'paragraph',
        'content': 'GO, if the intersection is clear. A green light gives you permission to proceed through the intersection or make the turn you intend (if not prohibited), but with caution. It does not mean “go blindly” – you should still quickly check that no one is running the opposing red light or that the intersection isn’t blocked. Also, if you\'re turning, yield to any pedestrians crossing or oncoming traffic (for example, if you\'re turning left on green without a green arrow, you must yield to oncoming vehicles).',
      },
      {
        'type': 'heading',
        'content': 'Yellow (Amber) Light',
      },
      {
        'type': 'paragraph',
        'content': 'CAUTION/Prepare to stop. A steady yellow light warns that the signal is about to turn red. If you see yellow and you can safely stop before the intersection, you should do so. If you are very close to the intersection when it turns yellow (too close to stop safely without sliding into the junction), you may proceed through, but do so with caution as the light will be red imminently. Do not speed up to “beat the yellow” – this often leads to running a red. The general rule is: yellow means stop, unless stopping abruptly would be unsafe (due to a vehicle right behind you, or you\'re already at the line).',
      },
      {
        'type': 'heading',
        'content': 'Red and Yellow together',
      },
      {
        'type': 'paragraph',
        'content': 'In some systems (like older signals or specific ones), you might see red and amber together – this typically means the light is about to turn green, but in many places that phase isn’t shown. In any case, until green appears, you must still stop. In Nigerian lights, usually it goes directly from red to green without showing red+amber together (that combined phase is more common in the UK, etc.).',
      },
      {
        'type': 'heading',
        'content': 'Green Arrow (Filter Arrow)',
      },
      {
        'type': 'paragraph',
        'content': 'Sometimes, a traffic light will have arrows. A green arrow indicates you can go specifically in the direction of the arrow, while other traffic may still be stopped. For example, a green right-turn arrow means you may make a protected right turn; oncoming traffic will have a red. Obey the arrow – if you intend to go in that direction, proceed; if not, and your main light is red, you must wait even if an arrow for another direction is green. When the arrow goes off, if it\'s a green arrow alone type signal, it might then give you a red or a green full circle after. Always move into the correct lane for the arrow you\'re following, and do not block lanes meant for other directions.',
      },
      {
        'type': 'heading',
        'content': 'Flashing Yellow',
      },
      {
        'type': 'paragraph',
        'content': 'A flashing yellow light (blinking amber) at an intersection means proceed with caution. It acts like a yield sign: slow down, look around, and go through carefully. Flashing yellow is often used during late-night operations of traffic lights or at pedestrian crossings to indicate you should be careful (and perhaps pedestrians could be crossing). You do not have to stop at a flashing yellow if the way is clear, but you must yield to any traffic or pedestrians.',
      },
      {
        'type': 'heading',
        'content': 'Flashing Red',
      },
      {
        'type': 'paragraph',
        'content': 'This is less common, but if a light is flashing red, it should be treated as a stop sign. Come to a complete stop, and then proceed when safe (obeying any right-of-way rules, such as yielding to cross traffic).',
      },
      {
        'type': 'heading',
        'content': 'Arrow with Red',
      },
      {
        'type': 'paragraph',
        'content': 'Sometimes you might see a situation like a red light together with a green arrow illuminated. This means the arrow movement is allowed (as a filtered turn) while all other movements are stopped. Only move in the direction of the green arrow. For instance, you could have a red full circle (no straight traffic) but a green right arrow (right turns can go). If you want to go straight in that scenario, you must stay stopped.',
      },
    ],
