  '7.2': {
    'title': 'Lesson 7',
    'contentBlocks': [
      {
        'type': 'heading',
        'content': 'Lesson 7: Traffic Lights and Hand Signals - Behavior at Traffic Lights:',
      },
      {
        'type': 'paragraph',
        'content': 'When approaching a green light, be prepared that it could turn yellow by the time you arrive (if it\'s a “stale” green, meaning it\'s been green a while). Anticipate the change and be ready to stop.',
      },
      {
        'type': 'paragraph',
        'content': 'Do not enter an intersection on green if you cannot clear it before it turns red or before cross-traffic would need it. For example, if traffic is backed up on the far side and your car would end up stuck in the middle when the light changes, wait on your side until there is space. Blocking intersections causes gridlock and is an offence.',
      },
      {
        'type': 'paragraph',
        'content': 'If the traffic light is not working (e.g., totally off or blinking in some error way), treat the intersection as an all-way stop: proceed carefully and use right-of-way rules (first-come or yield to the right, etc.) and courtesy.',
      },
      {
        'type': 'paragraph',
        'content': 'Some intersections might have special signals like a transit signal or a flashing pedestrian crossing light – follow the specific instructions for those (usually marked with signs).',
      },
      {
        'type': 'heading',
        'content': 'Obeying Officers over Lights',
      },
      {
        'type': 'paragraph',
        'content': 'If a traffic officer is directing traffic, their hand signals take priority over traffic lights. For example, if the light is green but an officer is signaling you to stop, you must stop. Officers may override lights during heavy traffic or if lights malfunction. Always watch for any police or traffic wardens at intersections and follow their hand instructions.',
      },
      {
        'type': 'heading',
        'content': 'Hand Signals by Drivers',
      },
      {
        'type': 'paragraph',
        'content': 'Although vehicles have light indicators, it\'s useful to know standard hand signals (in case your lights fail or to reinforce your intentions in daylight). These are made by putting your arm out the driver\'s window:\n\n- Left Turn: For a left-hand drive vehicle (steering on left side, as in Nigeria), left turn isn’t commonly signaled by hand since you would just use the indicator. However, if needed (say your indicators are broken), you could stick your left arm straight out to indicate you\'re turning left. (In some contexts, drivers use the right arm pointing left across the roof or vehicle – but this is uncommon; focus on using your indicators).\n\n- Right Turn: Extend your left arm out the window and bend it at the elbow 90 degrees so that your forearm points upward, palm facing forward. This is a classic signal for a right turn (in left-hand-drive cars). Essentially, an upright hand signal can indicate you intend to turn right. (Note: In right-hand-drive cars, one would extend the right arm to signal right, but in Nigeria most cars are LHD.)\n\n- Slowing Down or Stopping: Extend your left arm out and angle it downward, palm facing backward (or move your arm up and down). This gesture means you are slowing or stopping. It\'s a way to warn drivers behind you if your brake lights are not visible or not working.\n\n- Overtake Permission: Sometimes on highways, a driver ahead might stick their arm out and wave you on (swinging forward) indicating “you can overtake me now” – perhaps because they see the road ahead is clear. Use caution with such signals; it\'s not legally binding, just a courtesy. You still must ensure it\'s safe to overtake.\n\n- Always make hand signals clear and start them in good time (well before your turn or stop) so other road users understand your intention. Return your hands to the wheel when actually executing the maneuver. Hand signals are rarely used today except in specific situations, but knowing them is part of road knowledge.',
      },
      {
        'type': 'heading',
        'content': 'Traffic Officers\' Signals',
      },
      {
        'type': 'paragraph',
        'content': 'Officers (or traffic wardens) use arm gestures to control flow. Key ones include:\n\n- Stop Signal: If an officer stands facing you with arm raised up (palm toward you) or both arms outstretched to the sides, that generally means stop. Any arm raised towards traffic is a stop signal.\n\n- Go Signal: If the officer is motioning you forward (waving hand toward the body or pointing at you then motioning ahead) or has their side to you with arms motioning traffic from one direction, they may be letting your direction go. Often, if the officer\'s body is sideways to you and arms are extended, traffic parallel to their arms can move.\n\n- Turning Direction: An officer might point at a driver and then point to a direction indicating that driver should go in that direction or clear the intersection that way.\n\n- It can be tricky at first to understand police hand signals, but remember: their signals override traffic lights and signs for that moment. Just pay close attention and when in doubt, safely stop and wait until you are sure you\'re being signaled to proceed. Officers also sometimes use whistles – one long whistle might mean stop, two short whistles mean go, etc., but this can vary. Generally, follow the gestures.',
      },
      {
        'type': 'heading',
        'content': 'Pedestrian Signals',
      },
      {
        'type': 'paragraph',
        'content': 'At some crossings, there are pedestrian light signals (“Walk”/“don\'t Walk” or a walking man vs. standing man symbol). If you\'re driving, be aware that a flashing or steady “don\'t Walk” means pedestrians shouldn’t start crossing, but any who are already crossing will finish – yield to them. If the pedestrian light is showing “Walk”, your corresponding traffic light is likely red or about to turn red.',
      },
      {
        'type': 'heading',
        'content': 'Countdown Timers',
      },
      {
        'type': 'paragraph',
        'content': 'Some newer traffic lights have countdown timers indicating how many seconds until the next change. Use these to anticipate: for example, if you see the green light timer is at 3 seconds and counting down, prepare to stop because it will soon turn yellow then red. However, never start moving on a red just because the timer for cross-traffic is near zero – wait for your light to actually turn green.',
      },
      {
        'type': 'paragraph',
        'content': 'In summary, traffic signals are straightforward if you remember: Red = Stop, Green = Go (if safe), Yellow = Prepare to Stop (caution). And always, safety first – even a green light doesn\'t guarantee you won’t need to yield to avoid a collision. Communication via signals, whether light, hand, or officer\'s, is the language of the road.',
      },
    ],
  },
  '8.1': {
    'title': 'Lesson 8',
    'contentBlocks': [
      {
        'type': 'heading',
        'content': 'Lesson 8: Driving in Different Conditions - Introduction & Night Driving',
      },
      {
        'type': 'paragraph',
        'content': 'Driving safely requires adjusting to the road, weather, and time of day. In this lesson, we cover various challenging conditions and how to handle them: night driving, rain, fog/harmattan (dust haze), and driving in a convoy. Adapting your driving to these conditions is crucial for safety.',
      },
      {
        'type': 'heading',
        'content': 'Night Driving',
      },
      {
        'type': 'paragraph',
        'content': 'Driving after dark is riskier for several reasons: reduced visibility, difficulty judging distances, and increased likelihood of encountering drunk or fatigued drivers. Avoid night journeys if possible – but if you must:',
      },
      {
        'type': 'paragraph',
        'content': 'Ensure your headlights (and tail lights) are on and working from dusk to dawn. Use low-beam (dipped) headlights in well-lit urban areas and when following another vehicle. Use high-beam (full) headlights on dark roads for better visibility, but dip your headlights to low-beam when an oncoming vehicle is within sight or when driving close behind another car to avoid blinding others.',
      },
      {
        'type': 'paragraph',
        'content': 'Don\'t overdrive your headlights: This means do not drive so fast that you cannot stop within the distance you can see with your headlights. At night you should ideally drive slower because your reaction distance is limited by what your lights show.',
      },
      {
        'type': 'paragraph',
        'content': 'If an oncoming vehicle\'s high beams are blinding you, do not look directly at the light. Instead, avert your gaze slightly to the right edge of your lane and use the white line as a guide. Slow down if needed. You can flick your high beam quickly to remind them to dip their lights (but don\'t engage in a sustained “bright-light fight”). If you\'re completely dazzled and cannot see, it\'s safest to slow significantly or pull over momentarily (if safe) until your vision recovers.',
      },
      {
        'type': 'paragraph',
        'content': 'Keep your windshield clean to reduce glare and make sure your eyes are fit for night driving (if you wear glasses, an anti-reflective coating can help).',
      },
      {
        'type': 'paragraph',
        'content': 'Watch for pedestrians, cyclists, or animals on the road – they are much harder to see at night (often wearing dark clothing).',
      },
      {
        'type': 'paragraph',
        'content': 'Be aware that there are more impaired drivers at night (especially late nights). Drive very defensively – assume someone might do something erratic.',
      },
      {
        'type': 'paragraph',
        'content': 'If you feel sleepy, do not continue driving. Drowsiness can be as dangerous as drunk driving. If on a long trip, take breaks every couple of hours. If you start to nod off or lose concentration, pull over at a safe place, get out and stretch or take a nap. Never drive when you are too tired.',
      },
    ],
  },
  '8.2': {
    'title': 'Lesson 8',
    'contentBlocks': [
      {
        'type': 'heading',
        'content': 'Lesson 8: Driving in Different Conditions - Driving in Rain',
      },
      {
        'type': 'paragraph',
        'content': 'Rainy conditions can be treacherous because water on the road reduces tire grip and can cause skids (especially when rain first starts after a dry spell, as oil on the road mixes with water). When driving in rain:',
      },
      {
        'type': 'paragraph',
        'content': 'Slow down. It takes longer to stop on wet roads. Even with good tires, your braking distance can double on a wet surface.',
      },
      {
        'type': 'paragraph',
        'content': 'Use your wipers to keep the windshield clear. Make sure they are in good condition (old wiper blades can leave streaks).',
      },
      {
        'type': 'paragraph',
        'content': 'Turn on your headlights (low-beam) during rain, even in daytime, so that you can see and be seen better. (In heavy rain, it can appear almost dark, so lights help others notice you.)',
      },
      {
        'type': 'paragraph',
        'content': 'Ensure your defroster/demister is on to prevent the windshield from fogging up due to humidity. You might need to turn on the AC or heater and direct airflow to the windshield.',
      },
      {
        'type': 'paragraph',
        'content': 'Be extra gentle with steering, braking, and accelerating to avoid skids. If you need to slow down, ease off the accelerator early and brake gently. If you start skidding, do not slam the brakes; steer gently in the direction of the skid and moderate the brake until you regain traction.',
      },
      {
        'type': 'paragraph',
        'content': 'Watch out for puddles or flowing water. Driving through deep puddles can cause you to hydroplane (tires riding on water, losing contact with road) or can even flood your engine/ exhaust if too deep. If you must go through a puddle, slow right down, and afterwards, gently pump your brakes a few times to dry them.',
      },
      {
        'type': 'paragraph',
        'content': 'Increase your following distance. Give more space to the car ahead because if they stop suddenly, you will need more distance to stop on wet pavement. The two-second rule should become four seconds or more in rain.',
      },
    ],
  },
  '8.3': {
    'title': 'Lesson 8',
    'contentBlocks': [
      {
        'type': 'heading',
        'content': 'Lesson 8: Driving in Different Conditions - Driving in Fog or Harmattan Haze',
      },
      {
        'type': 'paragraph',
        'content': 'Fog, mist, or Harmattan dust haze (which is common in Nigeria\'s dry season in some regions) can severely reduce visibility. This is one of the most dangerous conditions because you simply cannot see hazards until you\'re very close.',
      },
      {
        'type': 'paragraph',
        'content': 'Use low-beam headlights or fog lights. Do NOT use high-beam in fog – it will reflect off the water droplets/dust and create a white wall, actually making visibility worse. Low beams aim down at the road and help you see a little and be seen by others. If you have fog lights (usually low-mounted lights), use them as well.',
      },
      {
        'type': 'paragraph',
        'content': 'Slow down significantly. If you can only see a few meters ahead, you must drive at a crawl if you continue at all. Many pile-up accidents happen in fog because drivers go too fast and can\'t stop when they suddenly come upon a hazard.',
      },
      {
        'type': 'paragraph',
        'content': 'Hazard Lights: In very thick fog or extremely poor visibility (like Harmattan dust storms), you may turn on your hazard lights in addition to low beams to make your vehicle more visible to those behind you. Use this with caution – you generally shouldn’t drive with hazards on in normal conditions, but in a scenario where visibility is near zero, it can prevent rear-end collisions.',
      },
      {
        'type': 'paragraph',
        'content': 'Pull Over if Necessary: If the fog or dust is so bad you cannot safely continue, pull completely off the road (preferably at a rest area or somewhere safe). If you stop on the shoulder, go as far to the right as possible, turn on hazards and parking lights. It may actually be safer to get well off the road than to creep along and risk being hit by others who can\'t see you.',
      },
      {
        'type': 'paragraph',
        'content': 'Keep windows clear: Use wipers and defrosters as needed because fog can also cause moisture build-up on windows.',
      },
      {
        'type': 'paragraph',
        'content': 'Be wary of other drivers not using lights – unfortunately some might not. Also watch out for slow-moving or stopped vehicles on the road.',
      },
    ],
  },
  '8.4': {
    'title': 'Lesson 8',
    'contentBlocks': [
      {
        'type': 'heading',
        'content': 'Lesson 8: Driving in Different Conditions - Driving in a Convoy & Other Conditions',
      },
      {
        'type': 'heading',
        'content': 'Driving in a Convoy',
      },
      {
        'type': 'paragraph',
        'content': 'A convoy refers to a group of vehicles traveling together, often for security (like VIP convoys) or events. If you find yourself driving in a convoy or around one:',
      },
      {
        'type': 'paragraph',
        'content': 'Maintain a reasonable speed and distance: Convoy drivers are instructed to obey speed limits and keep common-sense following distances. Stick to the convoy\'s pace; avoid either lagging far behind or tailgating too closely.',
      },
      {
        'type': 'paragraph',
        'content': 'Do not “cluster” dangerously: Each driver in a convoy should ensure they are not posing a hazard to other road users. Use indicators clearly when the group is maneuvering lanes or turns, so outsiders know what\'s happening.',
      },
      {
        'type': 'paragraph',
        'content': 'Stay in line: Typically, convoy vehicles drive in a line, often in one lane. Do not drift out of the line without reason, and do not overtake within the convoy unless necessary (and usually, convoy order is pre-determined).',
      },
      {
        'type': 'paragraph',
        'content': 'Be attentive: It\'s easy to get complacent in a convoy since you\'re “following the leader.” However, remain alert to traffic around you. Other drivers not in the convoy might cut in or out. Also, because convoys can sometimes be given passage by police escorts, be prepared for sudden changes (e.g., speeding up to go through a green light all together). Stay focused – convoy driving demands concentration.',
      },
      {
        'type': 'paragraph',
        'content': 'If you\'re not part of a convoy but encounter one (like a VIP or military convoy), it\'s often best to keep a respectful distance. Do not attempt to break into the middle of their line; let them go. Sometimes convoys have right of way granted by police – interfering could be dangerous or attract law enforcement attention.',
      },
      {
        'type': 'heading',
        'content': 'Heavy Wind or Thunderstorms',
      },
      {
        'type': 'paragraph',
        'content': 'In strong winds, your vehicle (especially high-sided vehicles like vans or SUVs) can be pushed laterally. Grip the steering wheel firmly and be ready to correct course. In a thunderstorm, apart from rain, be mindful of lightning and wind. It\'s generally safe inside a car during lightning (the car acts as a Faraday cage), but avoid touching metal parts connected to the outside. If wind is extremely severe (e.g., a squall or approaching tornado, very rare in Nigeria), seek shelter.',
      },
      {
        'type': 'heading',
        'content': 'Flooded Roads',
      },
      {
        'type': 'paragraph',
        'content': 'Never drive into water if you cannot gauge the depth. What looks shallow could stall your car or cause you to be swept away if there\'s a current. It only takes a foot or two of moving water to float a car. In heavy rain season, if streets are flooded, find an alternate route or wait until water subsides.',
      },
      {
        'type': 'heading',
        'content': 'Heat and Glare',
      },
      {
        'type': 'paragraph',
        'content': 'Under the hot sun (common in Nigeria), glare can be an issue. Wear sunglasses to reduce sun glare, especially during sunrise or sunset when the sun is low on the horizon. Also, extreme heat can affect your car – keep an eye on engine temperature, and never drive on under-inflated tires (they can overheat and burst in hot weather).',
      },
      {
        'type': 'heading',
        'content': 'In all special conditions',
      },
      {
        'type': 'paragraph',
        'content': 'The golden rule is slow down and increase your caution. Be ready for the unexpected and drive at a speed where you can react in time to what you can see (which might not be very far). Modern vehicles have many features (ABS brakes, stability control, etc.) that help, but nothing replaces prudent driving behavior. Safety first – if conditions are too dangerous, don\'t risk it; delay your trip or pull over until it\'s safer.',
      },
