      {
        'type': 'paragraph',
        'content': 'Becoming a licensed driver isn’t just about knowing the rules – it\'s also about cultivating the right attitude and habits for safe driving. This lesson delves into general safe driving techniques, including maintaining proper distances, and the concept of defensive driving – driving in a manner that anticipates and avoids potential hazards.',
      },
      {
        'type': 'heading',
        'content': 'Following Distance - The Two-Second Rule',
      },
      {
        'type': 'paragraph',
        'content': 'Always keep a safe gap between your car and the vehicle ahead. A handy rule of thumb is the “two-second rule.” Pick a stationary point on the road ahead (like a sign or tree). When the vehicle in front passes that point, start counting “one thousand and one, one thousand and two.” If you reach the same point before you finish, you\'re following too closely. In good conditions, two seconds is minimum. If the road is wet or visibility poor, extend it to 4 seconds or more. This buffer gives you time to react if the car ahead brakes suddenly. Remember: tailgating (driving too close) is very dangerous and can easily cause a crash if the lead driver stops suddenly.',
      },
      {
        'type': 'heading',
        'content': 'Stopping Distance',
      },
      {
        'type': 'paragraph',
        'content': 'Your total stopping distance is a combination of your reaction distance (how far you travel from the moment you decide to brake to the moment you actually start braking) plus the braking distance (how far the car travels from when brakes engage to when it stops). At higher speeds, stopping distance increases dramatically. For example, at 100 km/h, a car might need around 92 meters to stop in ideal conditions. If the road is wet or your tires/ brakes are poor, it will be even more. Always consider this when deciding your speed and following distance – you need enough space to stop safely if something happens.',
      },
      {
        'type': 'heading',
        'content': 'Avoiding Collisions - Space Cushion',
      },
      {
        'type': 'paragraph',
        'content': 'Besides the distance ahead, maintain space sideways. don\'t drive right alongside another vehicle if you can avoid it – either overtake or drop back, so you have room to maneuver if needed. Try to keep a cushion on at least one side of your vehicle at all times (e.g., if traffic is on your left, leave room on your right by keeping to the right side of your lane).',
      },
      {
        'type': 'heading',
        'content': 'Mirror Use and Blind Spots',
      },
      {
        'type': 'paragraph',
        'content': 'Check your mirrors frequently (every few seconds) to stay aware of who\'s around you. When planning any maneuver (turning, lane changing, overtaking, slowing), do the mirror-signal-shoulder check routine: Look at your rear-view and side mirrors, signal your intention, and check blind spots by glancing over your shoulder. This helps avoid side-swipe accidents.',
      },
    ],
  },
  '9.2': {
    'title': 'Lesson 9',
    'contentBlocks': [
      {
        'type': 'heading',
        'content': 'Lesson 9: Safe Driving Techniques and Defensive Driving - Defensive Mindset',
      },
      {
        'type': 'heading',
        'content': 'Defensive Driving Mindset',
      },
      {
        'type': 'paragraph',
        'content': 'Defensive driving means anticipating hazards and other road users\' mistakes, and preparing to avoid them. Here are principles of defensive drivers:',
      },
      {
        'type': 'heading',
        'content': 'Stay Alert',
      },
      {
        'type': 'paragraph',
        'content': 'Pay full attention to the road. Scan far ahead, not just at the car in front of you. Continuously move your eyes – check mirrors, speed, and the environment. Look out for potential problems (a child playing near the road, a car door that might open, brake lights far ahead, etc.).',
      },
      {
        'type': 'heading',
        'content': 'Anticipate others\' Actions',
      },
      {
        'type': 'paragraph',
        'content': 'Assume that other drivers might do something wrong. For example, at an intersection, even if you have green, watch for a late offender running their red. When following, imagine “What if that car brakes hard now? Am I ready?” If a car in the next lane is drifting a bit, assume they might come into your lane without warning.',
      },
      {
        'type': 'heading',
        'content': 'Have an Escape Plan',
      },
      {
        'type': 'paragraph',
        'content': 'Always think, “If the unexpected happens, where can I go?” For instance, if the car ahead blows a tire, can you swerve to the shoulder? If a vehicle comes at you head-on (in your lane trying to overtake improperly), be ready to slow down and move to the side. don\'t get boxed in – leave yourself a path out.',
      },
      {
        'type': 'heading',
        'content': 'Right Attitude',
      },
      {
        'type': 'paragraph',
        'content': 'Be patient and courteous. A defensive driver does not engage in road rage or competitions. If someone is in a hurry and tailgating you, don\'t aggravate them – safely move over and let them pass. It\'s not worth a confrontation. Obeying the rules is part of this, but also keeping cool if others don\'t. Remember, “a defensive driver assumes he is the only sane person on the road” – meaning you cannot rely on others to do the right thing, so you prepare to act correctly yourself.',
      },
      {
        'type': 'heading',
        'content': 'Adapt to Conditions',
      },
      {
        'type': 'paragraph',
        'content': 'As discussed in Lesson 8, a defensive driver adjusts speed and behavior for weather, traffic, and road conditions. They also avoid driving when impaired (by fatigue, alcohol, medications, strong emotions). If you\'re upset or very tired, it\'s defensive driving to decide not to drive until you\'re in a better state.',
      },
      {
        'type': 'heading',
        'content': 'Hazard Recognition',
      },
      {
        'type': 'paragraph',
        'content': 'Common hazards include: a ball rolling into the road (likely followed by a child), a parked car with brake lights on (might pull out), a broken-down vehicle partly in your lane, potholes, slick spots, animals ahead, etc. Continuously scanning helps catch these early. The earlier you spot a hazard, the more calmly and safely you can respond (slow down, change lane, etc.).',
      },
      {
        'type': 'heading',
        'content': 'Use of Horn and Lights',
      },
      {
        'type': 'paragraph',
        'content': 'Your horn is a tool to alert others of your presence or warn them, not to vent anger. Use it briefly if needed (for example, if a driver is drifting into your lane or a pedestrian is stepping into the road unwisely). Do not overuse the horn, especially not in anger – that can escalate road rage or confuse people. Flashing headlights is another way to signal (like flashing to remind someone they left high beams on, or to signal at an intersection that you are letting them go first). Use such signals with discretion; not everyone interprets them the same way.',
      },
      {
        'type': 'heading',
        'content': 'Avoid Distractions',
      },
      {
        'type': 'paragraph',
        'content': 'As repeated before, defensive driving means focusing on driving. That means no texting, minimal phone use (even hands-free can be distracting), and not being absorbed in conversations or adjusting the stereo for long. Watch the road, not billboards or your passengers.',
      },
      {
        'type': 'heading',
        'content': 'Speed Control',
      },
      {
        'type': 'paragraph',
        'content': 'Travel at a safe speed for conditions – which is not always the posted limit, sometimes it needs to be less. Never drive faster than the distance you can see. Around bends or in areas with tall crops or parked cars lining the street, slow down because something could be immediately out of sight.',
      },
      {
        'type': 'heading',
        'content': 'Following Heavy Vehicles',
      },
      {
        'type': 'paragraph',
        'content': 'Large trucks or buses have bigger blind spots and take longer to stop. Do not follow them too closely – if you can\'t see their mirrors, they likely can\'t see you. Also, be aware that heavy vehicles might roll back a bit on hill starts or have tire blowouts. Give them extra space and be careful when overtaking – they create wind turbulence. Remember the Highway Code\'s advice that smaller vehicles stand a greater risk in a collision with heavy trucks; it\'s physics, so respect the big vehicles and avoid cutting them off.',
      },
      {
        'type': 'heading',
        'content': 'Emotions and Driving',
      },
      {
        'type': 'paragraph',
        'content': 'Stay calm and do not let emotions dictate your driving. If another driver is aggressive or rude, the defensive approach is to distance yourself, not engage. don\'t take it personally. If you find yourself getting angry, take deep breaths or pull over to collect yourself. An emotional driver can make poor decisions.',
      },
      {
        'type': 'heading',
        'content': 'Continuous Learning',
      },
      {
        'type': 'paragraph',
        'content': 'Even after getting your license, keep learning and self-critiquing. Sometimes taking a defensive driving course or watching educational videos can sharpen your skills. Laws also can update, so stay informed.',
      },
      {
        'type': 'paragraph',
        'content': 'Driving is a skill that improves with experience, but only if you maintain good habits. Defensive driving isn’t about being timid; it\'s about being proactive, prepared, and in control. By practicing these techniques, you significantly reduce your risk of accidents and will be the kind of driver who “arrives alive” every trip.',
      },
    ],
  },
  '10.1': {
