      },
      {
        'type': 'paragraph',
        'content': 'Despite all precautions, sometimes emergencies or accidents happen on the road. Knowing what to do in these situations is part of being a responsible driver. This final lesson covers how to handle such events, including breakdowns, crashes, and basic first aid responsibilities.',
      },
      {
        'type': 'heading',
        'content': 'If Your Vehicle Breaks Down:',
      },
      {
        'type': 'heading',
        'content': 'Get Off the Road',
      },
      {
        'type': 'paragraph',
        'content': 'At the first sign of car trouble (engine sputtering, a loud noise, tire blowout, etc.), try to steer the vehicle out of moving traffic. Aim for the shoulder (right side) or an emergency lane. If you\'re on an expressway, take the next exit if possible, or pull off onto the hard shoulder as far to the right as you can.',
      },
      {
        'type': 'heading',
        'content': 'Warn Others',
      },
      {
        'type': 'paragraph',
        'content': 'Turn on your hazard warning lights immediately to signal to other drivers that you\'re having an issue. If you have a reflective warning triangle, place it on the road at least 30-50 meters behind your vehicle (on the same side) to give warning to oncoming traffic. In Nigeria, carrying a warning triangle is advised (and required for commercial vehicles). At night or in poor visibility, also keep your parking lights on.',
      },
      {
        'type': 'heading',
        'content': 'Stay Safe',
      },
      {
        'type': 'paragraph',
        'content': 'If you are on a busy road or expressway, it\'s often safest to remain in your vehicle with the seatbelt on until help arrives, especially if there\'s no safe place to stand. If you must step out (for example, to open the hood or change a tire), be very cautious of traffic. Stand off the road – not in front or behind your car, but preferably behind a guardrail or on the embankment if available. Have passengers also move to a safe spot if it\'s safer outside (like far off the road). In some cases (like a highway at night), staying in the vehicle might be safer; use judgment.',
      },
      {
        'type': 'heading',
        'content': 'Call for Help',
      },
      {
        'type': 'paragraph',
        'content': 'Call a roadside assistance service if you have one, or the police/road safety officials (FRSC). The FRSC emergency contact (like 122 or 112) can often dispatch help on highways. If you don\'t have a phone, you can raise the hood of your car and tie a white cloth or use other signals of distress so other drivers might stop to help or notify authorities.',
      },
      {
        'type': 'paragraph',
        'content': 'If you have a flat tire and know how to change it, only do so if you can get completely out of traffic lanes. Never change a tire in an exposed lane or close to moving traffic – it\'s better to call for help or drive (slowly) to a safer spot if possible than risk being hit.',
      },
      {
        'type': 'heading',
        'content': 'Tire Blowout',
      },
      {
        'type': 'paragraph',
        'content': 'If a tire blows out (you\'ll hear a loud bang or flapping, and the car may pull to one side), do not brake hard. Focus on keeping the car straight, take your foot off the accelerator, and let the car slow down gradually. Then gently steer towards the side of the road. Braking suddenly can cause you to lose control. Once stopped, put on hazards and address the situation (change tire or call for help).',
      },
      {
        'type': 'heading',
        'content': 'Brake Failure',
      },
      {
        'type': 'paragraph',
        'content': 'If you press the brake pedal and it sinks to the floor with no effect, you have a brake failure. Quickly do the following: Pump the brake pedal rapidly a few times – sometimes this builds enough pressure to engage the brakes. If that doesn\'t work, downshift to a lower gear (in an automatic, you can put it in “L” or 1, in a manual go to lower gears sequentially) to let engine braking slow you. Use the handbrake (parking brake) gradually – apply it slowly to avoid a skid. If collision seems imminent, try to steer into something soft (bushes, an uphill road, or scrape along a guardrail) rather than hitting another vehicle head-on. As a last resort, you can also use the engine cut-off (turn off ignition one notch, careful not to lock steering) to slow the engine, but steering may become harder. It\'s a scary situation – prevention (maintaining brakes) is key.',
      },
      {
        'type': 'heading',
        'content': 'Engine Overheat',
      },
      {
        'type': 'paragraph',
        'content': 'If your temperature gauge spikes or steam comes from under the hood, your engine may be overheating. In traffic, turn off the AC and perhaps turn on the heater (max heat) to draw heat from the engine. Pull over as soon as safe. Do not immediately open the radiator cap – it can spray hot coolant and cause burns. Wait for it to cool. You can check coolant level once cooled and add water/coolant if you have (in an emergency, water is okay). If not, call a mechanic. Overheating can ruin the engine, so don\'t try to keep driving.',
      },
