        'type': 'paragraph',
        'content': 'If you are involved in a collision, no matter how minor, you are legally required to stop. Do not drive away (hit-and-run is a serious crime). Turn on hazard lights. If it\'s a minor fender-bender with no injuries, if possible move the vehicles out of active traffic lanes to avoid a secondary accident (e.g., drive to the shoulder or side of the road). If someone is injured or the vehicles cannot move, put on hazards and possibly set out your triangle to warn other drivers.',
