        'type': 'heading',
        'content': 'Lesson 10: Managing Emergencies and Accidents - First Aid & Aftermath',
      },
      {
        'type': 'heading',
        'content': 'First Aid Basics',
      },
      {
        'type': 'paragraph',
        'content': 'If someone is injured and you are trained in first aid, you can help according to your training. If not trained, at least do the following:\n\n- Ensure the airway is open – if someone is unconscious, check that nothing is obstructing their mouth and that they are breathing. If not breathing and you know CPR, administer it. If you don\'t know CPR, emergency operators can sometimes guide you – but doing nothing until medics arrive could be worse.\n\n- Stop serious bleeding: If a person is bleeding heavily, take a clean cloth or bandage and apply firm pressure on the wound to slow bleeding. Elevate a bleeding limb if possible. Do not remove embedded objects; just apply pressure around them.\n\n- Treat for shock: After an accident, a victim may be in shock (pale, cold, faint, rapid pulse). Keep the person lying down if possible, with legs slightly raised (unless you suspect spinal injury or leg injury). Keep them warm with a blanket or clothing. Talk to them reassuringly.\n\n- don\'t move severely injured persons unless they are in immediate danger (like a fire). Moving someone with potential spinal injuries can worsen them. For instance, if someone is unconscious but breathing, it might be best to leave them in place until medical professionals arrive. The exception is if the car is on fire or at risk – then carefully drag them to safety with their body as straight as possible.\n\n- The Recovery Position: If an unconscious person is breathing and you need to leave to call help, place them on their side (recovery position) to keep the airway open and prevent choking on vomit.',
      },
      {
        'type': 'heading',
        'content': 'Calling Authorities',
      },
      {
        'type': 'paragraph',
        'content': 'By law, accidents involving injury or significant damage should be reported to the police. The FRSC or police will make a report. Even for minor accidents, it can be good to have an official report for insurance. When they arrive, cooperate and state clearly what happened. Do not admit fault at the scene in the heat of moment – just describe facts.',
      },
      {
        'type': 'heading',
        'content': 'Exchange Information',
      },
