        'type': 'paragraph',
        'content': 'With the other driver(s), exchange names, phone numbers, addresses, vehicle registration numbers, and insurance details. In Nigeria, also note the driver\'s license number. If possible, take photos of the scene and damage with your phone for evidence. Get contact of any witnesses around.',
      },
      {
        'type': 'heading',
        'content': 'Aftermath',
      },
