        'type': 'heading',
        'content': 'Fire in Vehicle',
      },
      {
        'type': 'paragraph',
        'content': 'If you see or smell smoke, or your car catches fire (from engine or elsewhere), act fast: signal and pull over immediately. Turn off the ignition (to stop fuel flow). Get everyone out and away from the car (at least 30 meters). If the fire is small (like engine compartment) and you have a fire extinguisher handy (which by law you should carry), you can attempt to put it out only if it\'s safe: pull the pin, aim at the base of flames (not at the flames tops), and sweep side to side. Do not open the hood fully if the engine\'s on fire – that can give the fire oxygen; just spray the extinguisher through any gap. If flames are large or near the fuel tank, do not try to fight it – get far away and call the fire service. Cars can burst into intense flames and even explode in extreme cases.',
