        'type': 'heading',
        'content': 'Obligations',
      },
      {
        'type': 'paragraph',
        'content': 'As a driver in Nigeria, you are obligated to help accident victims if you can. It is actually an offence for medical personnel or others to refuse help to accident victims. The good Samaritan principle is encouraged. The FRSC\'s slogan “Arrive Alive” and initiatives mean everyone should look out for each other on the road.',
